# Function: fetch_inaturalist_fungi

import json
import os
import tempfile
import time
from collections import Counter

import pandas as pd
import requests

INAT_URL = "https://api.inaturalist.org/v1/observations"
FUNGI_TAXON_ID = 47170
PER_PAGE = 200
TIMEOUT_S = 60
MIN_INTERVAL_S = 1.0
MAX_RETRIES = 6
USER_AGENT = "FaaSr-CURATE abby_soil_moisture_fungi workflow"


def _get_page(session, params, last_request):
    """GET one page with rate limiting and retry/backoff on transient errors."""
    attempt = 0
    while True:
        wait = MIN_INTERVAL_S - (time.monotonic() - last_request[0])
        if wait > 0:
            time.sleep(wait)
        last_request[0] = time.monotonic()
        try:
            resp = session.get(INAT_URL, params=params, timeout=TIMEOUT_S)
        except (requests.ConnectionError, requests.Timeout) as e:
            err = f"network error: {e}"
            resp = None
        else:
            if resp.status_code == 200:
                return resp.json()
            if resp.status_code != 429 and resp.status_code < 500:
                msg = f"iNaturalist API returned HTTP {resp.status_code}: {resp.text[:300]}"
                faasr_log(f"ERROR: {msg}")
                raise RuntimeError(msg)
            err = f"HTTP {resp.status_code}"
        attempt += 1
        if attempt > MAX_RETRIES:
            msg = f"iNaturalist API failed after {MAX_RETRIES} retries ({err})"
            faasr_log(f"ERROR: {msg}")
            raise RuntimeError(msg)
        backoff = min(2 ** attempt, 60)
        if resp is not None and resp.headers.get("Retry-After", "").isdigit():
            backoff = max(backoff, int(resp.headers["Retry-After"]))
        faasr_log(f"Transient error from iNaturalist ({err}); retry {attempt}/{MAX_RETRIES} in {backoff}s")
        time.sleep(backoff)


def fetch_inaturalist_fungi(folder: str, input1: str, output1: str) -> None:
    tmpdir = tempfile.mkdtemp()
    meta_path = os.path.join(tmpdir, "site_metadata.json")
    faasr_get_file(local_file=meta_path, remote_folder=folder, remote_file=input1)
    try:
        with open(meta_path) as f:
            meta = json.load(f)
        lat = float(meta["latitude"])
        lng = float(meta["longitude"])
        radius_m = float(meta["radius_m"])
    except Exception as e:
        faasr_log(f"ERROR: could not read latitude/longitude/radius_m from {input1}: {e}")
        raise
    radius_km = radius_m / 1000.0
    faasr_log(
        f"Fetching iNaturalist fungi (taxon_id={FUNGI_TAXON_ID}) within {radius_km} km "
        f"of lat={lat}, lng={lng}, all quality grades and dates"
    )

    base_params = {
        "taxon_id": FUNGI_TAXON_ID,
        "lat": lat,
        "lng": lng,
        "radius": radius_km,
        "order_by": "id",
        "order": "asc",
        "per_page": PER_PAGE,
    }

    session = requests.Session()
    session.headers.update({"User-Agent": USER_AGENT, "Accept": "application/json"})
    last_request = [0.0]

    seen_ids = set()
    month_counts = Counter()
    skipped_no_date = 0
    expected_total = None
    last_id = 0
    pages = 0

    while True:
        params = dict(base_params)
        if last_id:
            params["id_above"] = last_id
        payload = _get_page(session, params, last_request)
        pages += 1
        if expected_total is None:
            expected_total = int(payload.get("total_results", 0))
            faasr_log(f"iNaturalist reports total_results={expected_total}")
        results = payload.get("results") or []
        if not results:
            break
        for obs in results:
            oid = obs.get("id")
            if oid is None or oid in seen_ids:
                continue
            seen_ids.add(oid)
            observed_on = obs.get("observed_on")
            if not observed_on or len(str(observed_on)) < 7:
                skipped_no_date += 1
                continue
            month_counts[str(observed_on)[:7]] += 1
        page_max = max(o["id"] for o in results if o.get("id") is not None)
        if page_max <= last_id:
            msg = "iNaturalist id-based paging did not advance; aborting to avoid an infinite loop"
            faasr_log(f"ERROR: {msg}")
            raise RuntimeError(msg)
        last_id = page_max
        if pages % 10 == 0:
            faasr_log(f"... {pages} pages, {len(seen_ids)} records so far (last id {last_id})")

    retrieved = len(seen_ids)
    faasr_log(
        f"Retrieved {retrieved} iNaturalist fungi records in {pages} requests; "
        f"skipped {skipped_no_date} with no observed date; {sum(month_counts.values())} counted"
    )
    if retrieved != expected_total:
        faasr_log(
            f"WARNING: retrieved count {retrieved} differs from API total_results "
            f"{expected_total} (records may have been added/removed during the fetch)"
        )
    else:
        faasr_log(f"Retrieved count matches API total_results ({expected_total})")

    df = pd.DataFrame(
        sorted(month_counts.items()), columns=["month", "fungi_count"]
    )
    df["fungi_count"] = df["fungi_count"].astype(int)
    out_path = os.path.join(tmpdir, "monthly_fungi_counts.csv")
    df.to_csv(out_path, index=False)
    faasr_put_file(local_file=out_path, remote_folder=folder, remote_file=output1)
    faasr_log(f"Wrote {len(df)} months of fungi counts to {output1}")
